WITH eligible AS MATERIALIZED (SELECT DISTINCT o.customer_id FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id JOIN shipments sh ON sh.order_id=o.id WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01' AND p.active AND s.risk_tier>=4 AND (sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days')), fo AS MATERIALIZED (SELECT o.* FROM orders o JOIN eligible e ON e.customer_id=o.customer_id WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), captured AS MATERIALIZED (SELECT o.* FROM fo o WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=o.id AND pay.status='captured')), captured_counts AS (SELECT customer_id,count(*) AS captured_order_count FROM captured GROUP BY customer_id), item_revenue AS (SELECT o.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) AS net_item_revenue FROM captured o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no GROUP BY o.customer_id), promo_revenue AS (SELECT o.customer_id,sum(op.discount_amount) AS active_promotion_discount FROM fo o JOIN order_promotions op ON op.order_id=o.id JOIN promotions pr ON pr.id=op.promotion_id WHERE pr.active GROUP BY o.customer_id), late_counts AS (SELECT o.customer_id,count(*) AS late_shipment_count FROM fo o JOIN shipments sh ON sh.order_id=o.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days' GROUP BY o.customer_id), risky_counts AS (SELECT o.customer_id,count(DISTINCT ps.supplier_id) AS risky_supplier_count FROM fo o JOIN order_items oi ON oi.order_id=o.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id WHERE s.risk_tier>=4 GROUP BY o.customer_id), last_orders AS (SELECT customer_id,max(created_at) AS last_completed_at FROM fo GROUP BY customer_id) SELECT c.id AS customer_id,c.region,c.segment,cc.captured_order_count,COALESCE(ir.net_item_revenue,0)::numeric(20,2) AS net_item_revenue,COALESCE(pr.active_promotion_discount,0)::numeric(18,2) AS active_promotion_discount,lc.late_shipment_count,rc.risky_supplier_count,lo.last_completed_at FROM customers c JOIN eligible e ON e.customer_id=c.id LEFT JOIN captured_counts cc ON cc.customer_id=c.id LEFT JOIN item_revenue ir ON ir.customer_id=c.id LEFT JOIN promo_revenue pr ON pr.customer_id=c.id LEFT JOIN late_counts lc ON lc.customer_id=c.id LEFT JOIN risky_counts rc ON rc.customer_id=c.id LEFT JOIN last_orders lo ON lo.customer_id=c.id WHERE c.active